import{_ as s,c as n,o as l,b0 as e}from"./chunks/framework.Dmsv_Tiv.js";const u=JSON.parse('{"title":"LV010-G711简介","description":null,"frontmatter":{"title":"LV010-G711简介","date":"2025-12-19T19:31:43.000Z","icon":"famicons:logo-markdown","permalink":"/sdoc/acodec/encode/126b1ab9ed370a5c55dd17bc","index":true,"tags":null,"categories":null,"copyright":false,"keywords":null,"cover":null,"comments":null,"mathjax":null,"top":null,"description":null,"tdoc":{"detailDate":"2025-12-19T19:31:43.165Z","fulluuid":"c55dd17bc4db4831a05853599b055af8","useduuid":"c55dd17bc"}},"headers":[],"relativePath":"sdoc/acodec/encode/126b1ab9ed370a5c55dd17bc.md","filePath":"sdoc/25-音频编解码/10-编码/LV010-G711简介.md","lastUpdated":1767537778000}'),i={name:"sdoc/acodec/encode/126b1ab9ed370a5c55dd17bc.md"};function t(r,a,p,d,c,o){return l(),n("div",null,[...a[0]||(a[0]=[e(`<h1 id="lv010-g711简介" tabindex="-1">LV010-G711简介 <a class="header-anchor" href="#lv010-g711简介" aria-label="Permalink to &quot;LV010-G711简介&quot;">​</a></h1><h2 id="一、g711-简介" tabindex="-1">一、G711 简介 <a class="header-anchor" href="#一、g711-简介" aria-label="Permalink to &quot;一、G711 简介&quot;">​</a></h2><h3 id="_1-g711" tabindex="-1">1. G711 <a class="header-anchor" href="#_1-g711" aria-label="Permalink to &quot;1. G711&quot;">​</a></h3><p>G.711 是 ITU-T 制定的适用于语音频率范围的音频编码标准，它代表了对数 PCM（logarithmic pulse-code modulation）抽样标准，主要用于电话。它有以下特点：</p><ul><li>G.711 标准的音频 <strong>采样率 8K</strong>，单声道，编码的码率为 64kbps。</li><li><strong>G.711 编码后的数据为 8 位</strong>，因此， G.711 可以实现一半的数据压缩。</li></ul><p>一般来说，对于一般的 G.711 编码库，算法默认的输入数据长度为 40ms， 即 320 个采样点， 640Byte， 输出数据长度为 320Byte， 实现 2 倍的音频数据压缩。如果是 16k 采样率，那么一帧就是 640 个采样点，需要进行降采样处理，使用 8k 采样率重采。</p><p>算法复杂度低，压缩比小（CD音质&gt;400kbps），编解码延时最短（相对其它技术），但是占用的带宽较高。</p><h3 id="_2-a-law-和-mu-law" tabindex="-1">2. A law 和 Mu law <a class="header-anchor" href="#_2-a-law-和-mu-law" aria-label="Permalink to &quot;2.  A law 和 Mu law&quot;">​</a></h3><p>G.711 标准有 A law 和 Mu law 两种不同的编解码算法。Alaw 与 Mu law 本质的区别是 Mu law 保留了原始信号中最高有效位中最高 5 位的精度，然后用对数关系将剩下的信息映射到编码的最后 3 位；而 Alaw 则保留了原始信号中最高有效位中最高 4 位的精度，然后用对数关系将剩下的信息映射到编码的最后 4 位。</p><h4 id="_2-1-a-law" tabindex="-1">2.1 A law <a class="header-anchor" href="#_2-1-a-law" aria-label="Permalink to &quot;2.1 A law&quot;">​</a></h4><p>G.711 A law 主要用于欧洲， A law 可以表示的信号范围是 -4096 到 4096。 Alaw 每个样点的有效位数是 13 位（包含一个符号位），一般情况下，<strong>数据采样精度为 16 位</strong>。</p><h4 id="_2-2-mu-law" tabindex="-1">2.2 Mu law <a class="header-anchor" href="#_2-2-mu-law" aria-label="Permalink to &quot;2.2 Mu law&quot;">​</a></h4><p>G.711 Mu law 用于 美国，可以表示的信号范围是-8159 和 8159。Mu law 每个样点的有效位数是 14，但是一般情况下，<strong>数据采样精度为 16 位</strong>。</p><h2 id="二、g711-的内容" tabindex="-1">二、G711 的内容 <a class="header-anchor" href="#二、g711-的内容" aria-label="Permalink to &quot;二、G711 的内容&quot;">​</a></h2><p>G711 的内容是将 14bit(uLaw)或者 13bit(aLaw)采样的 PCM 数据编码成 8bit 的数据流，播放的时候在将此 8bit 的数据还原成 14bit 或者 13bit 进行播放，不同于 MPEG 这种对于整体或者一段数据进行考虑再进行编解码的做法，G711 是波形编解码算法，就是一个 sample 对应一个编码，所以压缩比固定为：</p><ul><li>8/14 = 57% (uLaw)</li><li>8/13 = 62% (aLaw)</li></ul><p>简单理解，G.711 就是语音模拟信号的一种非线性量化， bitrate 是 64kbps。</p><h2 id="三、相关计算" tabindex="-1">三、相关计算 <a class="header-anchor" href="#三、相关计算" aria-label="Permalink to &quot;三、相关计算&quot;">​</a></h2><p>已知：采样率 16K，采样点为 640，位深为 16 位，采用 G711A 和 G711U 进行压缩，每个采样点使用 8 位（1 字节）, 压缩时重采样为 8k，压缩比特率为 64000，那么压缩后一帧字节？</p><div class="language-md vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">md</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">帧时间长度 = 原始采样点数 / 原始采样 = 640 / 16,000 = 0.04秒 = 40毫秒</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">重采样后一帧采样点数 = 重采样率 × 帧时间长度 = 8000 × 0.04 = 320个采样点</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">方法一：基于采样点计算</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">压缩后一帧字节大小 = 采样点数 × 每个采样点字节数</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">= 320 × 1</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">= 320字节</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">方法二：基于比特率计算</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">压缩后一帧字节大小 = (比特率 × 帧时间长度) ÷ 8</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">= (64,000 × 0.04) ÷ 8</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">= 2,560 ÷ 8</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">= 320字节</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br></div></div><blockquote><p>参考资料：</p><p><a href="https://blog.csdn.net/li_wen01/article/details/81141085" target="_blank" rel="noreferrer">LPCM AAPCM G711 G726 AAC 音频采样、编码及帧大小计算-CSDN 博客</a></p><p><a href="https://blog.csdn.net/xxm524/article/details/46290227" target="_blank" rel="noreferrer">G.711 音频编码技术详解-CSDN 博客</a></p><p><a href="https://blog.csdn.net/qq_28258885/article/details/120215750" target="_blank" rel="noreferrer">音频处理——G711 标准详解_g711a 和 g711u 区别-CSDN 博客</a></p></blockquote>`,21)])])}const b=s(i,[["render",t]]);export{u as __pageData,b as default};
